const completed = new Map();
const inFlight = new Map();
let providerCalls = 0;

async function charge(reference, amount) {
  if (completed.has(reference)) return completed.get(reference);
  if (inFlight.has(reference)) return inFlight.get(reference);
  const promise = (async () => {
    providerCalls++;
    await new Promise((resolve) => setTimeout(resolve, 10));
    const payment = { reference, amount };
    completed.set(reference, payment);
    return payment;
  })().finally(() => inFlight.delete(reference));
  inFlight.set(reference, promise);
  return promise;
}

const [a, b] = await Promise.all([charge("ORD-1", 500), charge("ORD-1", 500)]);
const c = await charge("ORD-1", 500);
await charge("ORD-2", 500);
console.log(a === b, b === c, providerCalls);

