function bump(version, type) {
  const [major, minor, patch] = version.split(".").map(Number);
  if (type === "major") return `${major + 1}.0.0`;
  if (type === "minor") return `${major}.${minor + 1}.0`;
  return `${major}.${minor}.${patch + 1}`;
}

const rank = { patch: 0, minor: 1, major: 2 };
const pending = ["patch", "minor", "patch"];
const highest = pending.reduce((a, b) => (rank[b] > rank[a] ? b : a));
console.log(bump("1.4.2", highest), bump("1.4.2", "major"), bump("0.9.9", "patch"));

function satisfiesCaret(version, base) {
  const [vMaj, vMin, vPat] = version.split(".").map(Number);
  const [bMaj, bMin, bPat] = base.split(".").map(Number);
  const atLeast = vMaj > bMaj || (vMaj === bMaj && (vMin > bMin || (vMin === bMin && vPat >= bPat)));
  if (!atLeast) return false;
  if (bMaj > 0) return vMaj === bMaj;
  if (bMin > 0) return vMaj === 0 && vMin === bMin;
  return vMaj === 0 && vMin === 0 && vPat === bPat;
}

console.log(
  satisfiesCaret("1.9.0", "1.3.0"),
  satisfiesCaret("2.0.0", "1.3.0"),
  satisfiesCaret("0.1.7", "0.1.0"),
  satisfiesCaret("0.2.0", "0.1.0"),
);

