import { ValidationError } from "@zudojs/errors";

function validate(request) {
  const issues = [];
  if (!request.reference.trim()) issues.push({ field: "reference", message: "is required" });
  if (!request.email.includes("@")) issues.push({ field: "email", message: "must be an email address" });
  if (!Number.isSafeInteger(request.amountKobo) || request.amountKobo <= 0) {
    issues.push({ field: "amountKobo", message: "must be a positive whole number of kobo" });
  }
  if (issues.length > 0) throw new ValidationError("The payment request is invalid.", { code: "ERR_PAYMENT_INVALID", issues });
}

try {
  validate({ reference: "ORD-8", email: "ada", amountKobo: 12.5 });
  console.log("valid");
} catch (error) {
  console.log(error.code, error.issues.map((i) => i.field).join(","));
}

