const completed = new Map();
const inFlight = new Map();
let calls = 0;
const provider = async (reference, amount) => {
  calls++;
  await new Promise((resolve) => setTimeout(resolve, 5));
  return { reference, amount };
};

async function charge(reference, amount) {
  const done = completed.get(reference);
  if (done) {
    if (done.amount !== amount) throw new Error("conflict");
    return done;
  }
  const pending = inFlight.get(reference);
  if (pending) return pending;
  const promise = provider(reference, amount)
    .then((payment) => {
      completed.set(reference, payment);
      return payment;
    })
    .finally(() => inFlight.delete(reference));
  inFlight.set(reference, promise);
  return promise;
}

await Promise.all([charge("ORD-1", 900), charge("ORD-1", 900)]);
await charge("ORD-1", 900);
console.log("calls:", calls);
try {
  await charge("ORD-1", 100);
} catch (error) {
  console.log(error.message);
}

