function toResult(body) {
  if (!body.status || !body.data) throw new Error(`refused: ${body.message}`);
  if (body.data.status === "success") return { status: "success", providerReference: body.data.reference };
  return { status: "failed", providerReference: body.data.reference, reason: body.data.gateway_response ?? body.data.status };
}

console.log(JSON.stringify(toResult({ status: true, message: "Charge attempted", data: { status: "success", reference: "ps_1" } })));
console.log(JSON.stringify(toResult({ status: true, message: "Charge attempted", data: { status: "failed", reference: "ps_2", gateway_response: "Do Not Honor" } })));
try {
  toResult({ status: false, message: "Duplicate Transaction Reference" });
} catch (error) {
  console.log(error.message);
}

