function diffApi(actual, approved) {
  const a = new Set(actual);
  const b = new Set(approved);
  return {
    added: [...a].filter((name) => !b.has(name)).sort(),
    removed: [...b].filter((name) => !a.has(name)).sort(),
  };
}

const approved = ["createPaymentService", "createPaystackProvider", "isPaymentError", "PaymentErrorCode"];
