function createFakeProvider({ decline = [] } = {}) {
  const requests = [];
  return {
    requests,
    async charge(request) {
      requests.push(request);
      if (decline.includes(request.authorizationCode)) return { status: "failed", reason: "Insufficient Funds" };
      return { status: "success" };
    },
  };
}

const provider = createFakeProvider({ decline: ["AUTH_broke"] });
const a = await provider.charge({ reference: "ORD-1", authorizationCode: "AUTH_ok" });
const b = await provider.charge({ reference: "ORD-2", authorizationCode: "AUTH_broke" });
